  "claims": [
    {
      "claim": "The query is a 3-hydroxy-1,4-naphthoquinone with a lipophilic trans-4-(4-chlorophenyl)cyclohexyl substituent; the closest visible analog buparvaquone (same core, tert-butyl instead of chlorophenyl) has very poor aqueous solubility (<300 ng/mL) and required an optimized SMEDDS to reach 100% dissolution, indicating a severe solubility/dissolution liability for this chemotype.",
      "card_ids": ["C136", "C112"]
    },
    {
      "claim": "L6 records show buparvaquone (58C80) is rapidly hydroxylated in human liver microsomes mainly by CYP2C9, producing a single CYP2C9-dependent metabolite with 11-fold interindividual variation; this is affirmative measured hepatic first-pass metabolism for the closest analog.",
      "card_ids": ["C220", "C233"]
    },
    {
      "claim": "Other 3-hydroxy-1,4-naphthoquinones (AN-04, AN-03) are positive for CYP2C8/CYP2C9, and AN-04 has a measurable HLM intrinsic clearance of 36.8 µL/min/mg, supporting oxidative metabolism of the naphthoquinone core.",
      "card_ids": ["C209", "C236", "C194"]
    },
    {
      "claim": "No visible record provides a direct absolute oral bioavailability measurement or matched oral/IV exposure for the query; the L1 gold contexts are for unrelated molecules and do not provide affirmative high-F evidence for this query.",
      "card_ids": ["C15", "C10", "C13", "C02", "C05"]
    },
    {
      "claim": "Combining the close-analog solubility/dissolution liability with the measured hepatic first-pass metabolism provides coherent affirmative evidence that F is below 20% in the fasted state.",
      "card_ids": ["C136", "C112", "C220", "C233", "C194"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C220", "C233", "C194", "C209", "C236"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule in the fasted state.",
    "No matched oral versus intravenous exposure data for the query.",
    "No query-specific solubility, permeability, or metabolism measurement; the closest analog is buparvaquone.",
    "Transfer from buparvaquone to atovaquone is uncertain because the cyclohexyl substituent differs (tert-butyl vs 4-chlorophenyl) and metabolic fate may differ.",
    "In vitro microsomal CLint and solubility do not directly quantify in vivo F; no formulation or dose information for the query.",
    "Fasted-state condition is not directly represented in the visible records."
  ],
  "decision_summary": "Flip to low: L6 provides affirmative hepatic first-pass metabolism for the closest analog buparvaquone (rapid CYP2C9 hydroxylation), which, combined with the close-analog very poor aqueous solubility and SMEDDS-dependent dissolution, coherently supports F<20% in the fasted state. No direct query F or matched oral/IV data exists, so confidence is moderate and transferability is the main uncertainty."
}

